script:
(function () {
  'use strict';
  // Expected return of one investment across probability-weighted scenarios:
  //   E(R) = sum(p_i x r_i)                  (probabilities p_i must total 100%)
  //   variance = sum(p_i x (r_i - E(R))^2),  standard deviation = sqrt(variance)
  //   coefficient of variation = standard deviation / E(R)
  // Checked in Node (er.test.js): 25% at -8%, 50% at 8%, 25% at 20% -> E(R) 7%, variance 0.0099,
  // standard deviation 9.9499%; textbook two-state case 50% at +30% and 50% at -10% -> 10% and 20%;
  // 30/40/30 at 25%/15%/5% -> 15% and 7.746% (sqrt 0.006); a single certain scenario (100% at 6%)
  // -> standard deviation 0; probabilities totalling 99.9% are rejected.
  var MIN_ROWS = 2, MAX_ROWS = 10, TOLERANCE = 0.005; // percentage points allowed off 100%
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var OUTPUTS = ['erExpected', 'erStd', 'erGain', 'erProbTotal', 'erVar', 'erCv', 'erRange', 'erEnd', 'erLoss'];
  var INPUT_CLASS = 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none';

  // --- calc start
  // scenarios: [{ p: probability as a decimal, r: return as a decimal }], probabilities sum to 1.
  function expectedReturn(scenarios) {
    var mean = 0, variance = 0, loss = 0, i;
    for (i = 0; i < scenarios.length; i++) mean += scenarios[i].p * scenarios[i].r;
    var rows = [];
    for (i = 0; i < scenarios.length; i++) {
      var s = scenarios[i], dev = s.r - mean, wsq = s.p * dev * dev;
      variance += wsq;
      if (s.r < 0) loss += s.p;
      rows.push({ p: s.p, r: s.r, weighted: s.p * s.r, dev: dev, wsq: wsq });
    }
    var rets = scenarios.map(function (s) { return s.r; });
    return {
      mean: mean, variance: variance, std: Math.sqrt(variance), lossChance: loss, rows: rows,
      worst: Math.min.apply(null, rets), best: Math.max.apply(null, rets)
    };
  }
  // --- calc end

  function el(id) { return document.getElementById(id); }
  function fix(x, dp) {
    if (Math.abs(x) < 0.5 * Math.pow(10, -dp)) x = 0;
    return x.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }).replace(/^-/, '−');
  }
  function pct(x) { return fix(x * 100, 2) + '%'; }
  function usd(x) { return money.format(Math.abs(x) < 0.005 ? 0 : x).replace(/^-/, '−'); }

  function rowEls() { return Array.prototype.slice.call(el('erRows').children); }

  function syncButtons() {
    var n = rowEls().length;
    el('erAdd').disabled = n >= MAX_ROWS;
    el('erRemove').disabled = n <= MIN_ROWS;
  }

  function numberField(id, label, min, max, step) {
    var group = document.createElement('div');
    group.className = 'input-group';
    var input = document.createElement('input');
    input.type = 'number';
    input.id = id;
    input.className = INPUT_CLASS;
    input.setAttribute('aria-label', label);
    input.min = min;
    if (max) input.max = max;
    input.step = step;
    input.setAttribute('inputmode', 'decimal');
    var affix = document.createElement('span');
    affix.className = 'input-affix';
    affix.textContent = '%';
    group.appendChild(input);
    group.appendChild(affix);
    return { group: group, input: input };
  }

  function addRow() {
    var n = rowEls().length + 1;
    if (n > MAX_ROWS) return;
    var wrap = document.createElement('div');
    wrap.className = 'grid grid-cols-[5.5rem_minmax(0,1fr)_minmax(0,1fr)] items-center gap-2';
    var name = document.createElement('span');
    name.id = 'erName' + n;
    name.className = 'text-sm text-ink-muted';
    name.textContent = 'Scenario ' + n;
    var prob = numberField('erProb' + n, 'Probability of scenario ' + n, '0', '100', '1');
    var ret = numberField('erRet' + n, 'Return in scenario ' + n, '-100', '', '0.1');
    wrap.appendChild(name);
    wrap.appendChild(prob.group);
    wrap.appendChild(ret.group);
    el('erRows').appendChild(wrap);
    syncButtons();
    update();
    prob.input.focus();
  }

  function removeRow() {
    var rows = el('erRows');
    if (rowEls().length <= MIN_ROWS) return;
    rows.removeChild(rows.lastElementChild);
    syncButtons();
    update();
  }

  function clear(msg) {
    var error = el('erError');
    error.hidden = !msg;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { el(id).textContent = '–'; });
    el('erTable').innerHTML = '';
  }

  function update() {
    var scenarios = [], labels = [], msg = '', total = 0;
    var count = rowEls().length;
    for (var i = 1; i <= count; i++) {
      var pIn = el('erProb' + i), rIn = el('erRet' + i);
      var pTxt = pIn.value.trim(), rTxt = rIn.value.trim();
      if (pTxt === '' && rTxt === '') continue;
      var p = parseFloat(pTxt), r = parseFloat(rTxt);
      if (!isFinite(p) || p < 0 || p > 100) { msg = 'Scenario ' + i + ': enter a probability from 0% to 100%.'; break; }
      if (!isFinite(r) || r < -100 || r > 10000) { msg = 'Scenario ' + i + ': enter a return from -100% to 10,000%.'; break; }
      total += p;
      scenarios.push({ p: p / 100, r: r / 100 });
      labels.push(i);
    }
    var amount = parseFloat(el('erAmount').value);
    if (el('erAmount').value.trim() === '') amount = 0;
    if (!msg && !scenarios.length) msg = 'Enter at least one scenario.';
    if (!msg && (!isFinite(amount) || amount < 0 || amount > 1e12)) msg = 'Enter an amount invested from $0 to $1 trillion.';
    if (!msg && Math.abs(total - 100) > TOLERANCE) {
      msg = 'The probabilities add up to ' + fix(total, 2) + '%. Adjust them so they total exactly 100%.';
    }
    if (msg) {
      clear(msg);
      if (scenarios.length) el('erProbTotal').textContent = fix(total, 2) + '%';
      return;
    }
    clear('');

    var res = expectedReturn(scenarios);
    el('erExpected').textContent = pct(res.mean);
    el('erStd').textContent = pct(res.std);
    el('erGain').textContent = amount > 0 ? usd(amount * res.mean) : '–';
    el('erProbTotal').textContent = fix(total, 2) + '%';
    el('erVar').textContent = fix(res.variance, 6);
    el('erCv').textContent = Math.abs(res.mean) > 1e-12 ? fix(res.std / res.mean, 3) : 'Not defined at 0% expected return';
    el('erRange').textContent = pct(res.worst) + ' / ' + pct(res.best);
    el('erEnd').textContent = amount > 0 ? usd(amount * (1 + res.mean)) : '–';
    el('erLoss').textContent = pct(res.lossChance);
    el('erTable').innerHTML = res.rows.map(function (row, k) {
      return '<tr><td>Scenario ' + labels[k] + '</td><td>' + pct(row.p) + '</td><td>' + pct(row.r) + '</td><td>' +
             pct(row.weighted) + '</td><td>' + pct(row.dev) + '</td><td>' + fix(row.wsq, 6) + '</td></tr>';
    }).join('') + '<tr><th scope="row">Total</th><td>' + fix(total, 2) + '%</td><td></td><td>' + pct(res.mean) +
      '</td><td></td><td>' + fix(res.variance, 6) + '</td></tr>';
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('erForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('erAdd').addEventListener('click', addRow);
    el('erRemove').addEventListener('click', removeRow);
    syncButtons();
    update();
  });
})();
